<script setup lang="ts">import{Head,Link}from'@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import{Button}from'@/components/ui/button';defineProps<{packages:any[]}>();const money=(v:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v/100);</script><template><Head title="Sponsorship Packages"/><div class="space-y-6 p-6"><div class="flex justify-between"><PageHeader title="Sponsorship Packages" description="Reusable commercial sponsorship offerings and included placements."/><Link href="/admin/sponsorship-packages/create"><Button>Create Package</Button></Link></div><div class="overflow-hidden rounded-xl border"><table class="w-full text-sm"><thead class="bg-muted/50"><tr><th class="p-3 text-left">Package</th><th>Duration</th><th>Placements</th><th>Price</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in packages" :key="p.id" class="border-t"><td class="p-3"><div class="font-medium">{{p.name}}</div><div class="text-muted-foreground">{{p.code}}</div></td><td>{{p.duration_days}} days</td><td>{{p.placements.length}}</td><td>{{money(p.package_price_cents)}}</td><td>{{p.is_active?'Active':'Inactive'}}</td><td class="p-3 text-right"><Link :href="`/admin/sponsorship-packages/${p.id}/edit`"><Button size="sm" variant="outline">Edit</Button></Link></td></tr></tbody></table></div></div></template>